// Parse input do FastAPI
const data = $input.first().json;

return {
  sender_id: data.from,
  sender_name: data.name,
  message: data.message_cleaned || '',
  original_message: data.original_message || '',
  timestamp: data.timestamp || Date.now()
};

// Monta histórico em formato [{role, content}] para o LLM
const rows = $input.first().json;
const sender_id = $input.all()[0].json.sender_id;

// Filtra linhas do usuário atual
const user_history = rows.filter(row => row.telefone === sender_id);

// Ordena por timestamp
user_history.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

// Converte para formato [{role, content}]
const formatted_history = user_history.map(row => ({
  role: row.role,
  content: row.content
}));

return {
  conversation_history: formatted_history,
  history_count: formatted_history.length,
  last_message_timestamp: user_history.length > 0 ? user_history[user_history.length - 1].timestamp : null
};

