// Parse da resposta do LLM
const response_text = $input.first().json.response || '';

try {
  // Tenta extrair JSON da resposta (LLM pode adicionar texto extra)
  const json_match = response_text.match(/\{[\s\S]*\}/);
  if (!json_match) {
    return {
      action: 'erro',
      resposta: 'Desculpe, tive dificuldade em processar sua mensagem. Tente novamente.',
      raw_response: response_text
    };
  }

  const parsed = JSON.parse(json_match[0]);

  return {
    action: parsed.action || 'mensagem',
    nome: parsed.nome || '',
    data: parsed.data || '',
    horario: parsed.horario || '',
    resposta: parsed.resposta || 'Desculpe, não consegui entender. Tente novamente.',
    raw_response: response_text,
    parse_success: true
  };
} catch (e) {
  return {
    action: 'erro',
    resposta: 'Desculpe, tive um problema ao processar. Tente novamente.',
    raw_response: response_text,
    error: e.message,
    parse_success: false
  };
}
